select * from payments;


# Operations wants a list of all students enrolled after 1 June 2025
select student_id,student_name, enrollment_date from students
where enrollment_date>'2025-06-01'
order by enrollment_date desc;

#The data team needs a temporary table named analyst_notes to store follow-up notes for students.

#Create the table with:
#• note_id as the primary key
#• student_id as a required field
#• note_text as a required field
#• created_at as a date/time field

create table analyst_notes(
note_id varchar(10) not null primary key,
student_id varchar(10) not null,
note_text varchar(100) not null,
created_at timestamp,
constraint fk_student_id foreign key(student_id) references students(student_id)
);

# Management wants to review the five most recently enrolled students.
select student_id,student_name, enrollment_date from students
order by enrollment_date desc
limit 5;

# Academic Management wants to know the overall average score across all assessment records.
select  round(avg(score),2) from assessments;

# Operations wants to understand how many students are enrolled in each program.
#select programs.program_name, count(students.student_id) from programs
#inner join students on programs.

# Finance wants to know the total amount collected from all payment transactions.
select sum(amount_paid) from payments;

alter table analyst_notes add status ENUM('Open','Closed') not null;

drop table if exists analyst_notes;

SELECT d.department_name AS de,COUNT(DISTINCT s.student_id) AS sc,ROUND(AVG(att.attendance_percentage), 2) AS aap,
ROUND(AVG(a.average_score), 2) AS aas,SUM(p.course_fee) AS tef,SUM(pay.total_paid, 0) AS Tc,
SUM(p.course_fee) - SUM(pay.total_paid, 0) AS Outs,
ROUND(SUM(pay.total_paid, 0) / SUM(p.course_fee) * 100, 2) AS cr,
SUM(
CASE
WHEN att.attendance_percentage < 75 OR a.average_score < 60
THEN 1 ELSE 0
END
) AS Student attention
FROM departments d
JOIN programs p ON d.department_id = p.department_id
JOIN students s ON p.program_id = s.program_id
LEFT JOIN (
SELECT student_id,
AVG(CASE WHEN status = 'Present' THEN 100 ELSE 0 END)
AS attendance_percentage
FROM attendance
GROUP BY student_id
) att ON s.student_id = att.student_id

LEFT JOIN (
SELECT student_id, AVG(score) AS average_score
FROM assessments
GROUP BY student_id
) a ON s.student_id = a.student_id

LEFT JOIN (
SELECT student_id, SUM(amount_paid) AS total_paid
FROM payments
GROUP BY student_id
) pay ON s.student_id = pay.student_id
GROUP BY d.department_id, d.department_name;
